// src/pages/LoginPage.jsx
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';

function LoginPage() {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [message, setMessage] = useState({ text: '', type: '' });
  const [jwtToken, setJwtToken] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate(); 

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setMessage({ text: '', type: '' });
    setJwtToken('');
    try {
      const response = await axios.post('http://localhost:5000/api/login', formData);
      const { token } = response.data;
      
      localStorage.setItem('authToken', token);
      setJwtToken(token);
      setMessage({ text: '✔ Đăng nhập thành công! Đang chuyển hướng...', type: 'success' });

      setTimeout(() => {
        navigate('/'); 
      }, 2000);
      
    } catch (err) {
      const errorMsg = err.response?.data?.message || 'Email hoặc mật khẩu không đúng!';
      setMessage({ text: '✖ ' + errorMsg, type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    /* --- (THAY ĐỔI) SỬ DỤNG BỐ CỤC 2 CỘT --- */
    <div className="auth-split-container">
      {/* --- Cột 1: Welcome --- */}
      <div className="auth-welcome-section">
        {/* Bạn có thể thêm logo hoặc ảnh minh họa ở đây */}
        {/* <img src="/path/to/illustration.svg" alt="Welcome" className="welcome-illustration-split" /> */}
        <h2>Chào mừng bạn trở lại!</h2>
        <p>Đăng nhập để tiếp tục quản lý công việc và dự án của bạn.</p>
      </div>

      {/* --- Cột 2: Form --- */}
      <div className="auth-form-section"> {/* 👈 Đổi từ auth-card */}
        <h2>Đăng nhập</h2>
        <form className="auth-form" onSubmit={handleSubmit}>
          <input
            type="email"
            name="email"
            placeholder="Email"
            onChange={handleChange}
            required
          />
          <input
            type="password"
            name="password"
            placeholder="Mật khẩu"
            onChange={handleChange}
            required
          />

          {/* --- (THAY ĐỔI) Thêm "Ghi nhớ" & "Quên mật khẩu" --- */}
          <div className="form-options">
            <label className="checkbox-container">
              <input type="checkbox" name="remember" /> Ghi nhớ tôi
              <span className="checkmark"></span>
            </label>
            <div className="forgot-password-link">
              <Link to="/forgot-password">Quên mật khẩu?</Link>
            </div>
          </div>
        
          <button type="submit" className="auth-button" disabled={isLoading}>
            {isLoading ? 'Đang đăng nhập...' : 'Đăng nhập'}
          </button>
        </form>
      
        {/* Các thông báo và link đăng ký giữ nguyên BÊN TRONG .auth-form-section */}
        {message.text && (
          <div className={`message-box ${message.type}`}>
            {message.text}
          </div>
        )}
      
        {jwtToken && (
          <div className="jwt-token-box">
            <strong>JWT Token nhận được:</strong>
            {jwtToken}
          </div>
        )}

        <div className="register-link">
          Chưa có tài khoản? <Link to="/register">Đăng ký ngay</Link>
        </div>
      </div>
    </div> /* --- Đóng .auth-split-container --- */
  );
}

export default LoginPage;
